class Solution {
  public int climbStairs(int n, int[] costs) {
    long INF = Long.MAX_VALUE / 4;
    long[] dp = new long[n + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int j = 1; j <= n; j++) {
      for (int d = 1; d <= 3 && d <= j; d++) {
        dp[j] = Math.min(dp[j], dp[j - d] + costs[j - 1] + (long) d * d);
      }
    }
    return (int) dp[n];
  }
}
